import pytest

from .harness import Persona, PlaytestClient


async def _publish_pack(client: PlaytestClient, workspace_id: str, version: str, enemy_hp: int) -> None:
    await client.command("CreateAuthoringWorkspace", payload={"workspace_id": workspace_id, "namespace": "p8"})
    await client.command("UpsertDraftDefinition", payload={"workspace_id": workspace_id, "draft_id": "npc", "definition_type": "npc_template", "key": "p8:npc/raider", "source": {"license_id": "CC0-1.0"}, "data": {"name": "P8 Raider", "max_hp": enemy_hp, "attack_bonus": -5, "defense": 5, "behavior_profile": "aggressive_melee"}})
    await client.command("UpsertDraftDefinition", payload={"workspace_id": workspace_id, "draft_id": "encounter", "definition_type": "encounter_template", "key": "p8:encounter/camp", "source": {"license_id": "CC0-1.0"}, "data": {"enemy_ref": "p8:npc/raider", "player_side": "heroes", "enemy_side": "enemies", "player_position": 0, "enemy_position": 2}})
    validation = await client.command("ValidateAuthoringWorkspace", payload={"workspace_id": workspace_id}); assert validation["result"]["quality_report"]["valid"] is True
    await client.command("PublishAuthoringWorkspace", payload={"workspace_id": workspace_id, "version": version})


