        await dm.command("CloseGameSession", campaign_id="cmp_p8", payload={"session_id":"p8_session"}); recap = (await dm.get("/api/v1/sessions/p8_session/recap"))["data"]; assert recap["event_count"] > 0; journal=(await player.get("/api/v1/actors/p8_hero/journal"))["data"]; assert journal["entries"]
        replay = await dm.get("/api/v1/campaigns/cmp_p8/replay-hash"); assert replay["matches_live"] is True
        package = (await dm.get("/api/v1/campaigns/cmp_p8/export-package"))["data"]; validation = await dm.http.post("/api/v1/imports/campaign/validate", json=package, headers=dm.headers); validation.raise_for_status(); assert validation.json()["data"]["valid"] is True
        recovery = await dm.http.post("/api/v1/admin/recovery-probe/cmp_p8", headers={"x-principal-id":"admin","x-principal-roles":"admin"}); recovery.raise_for_status(); assert recovery.json()["data"]["success"] is True
